/**
 * Parse a duration string into milliseconds.
 *
 * Examples:
 *   parseMillis("2s")   // returns 2000
 *   parseMillis("2s") returns 2000
 *   parseMillis("500")  // returns 500
 *   parseMillis("500ms") // returns 500
 *   parseMillis("abc")  // returns null (invalid input returns null)
 */
export function parseMillis(value: string): number | null {
  const match = /^(\d+)(ms|s)?$/.exec(value.trim());
  if (!match) return null;

  const amount = Number(match[1]);
  const unit = match[2] ?? "ms";

  return unit === "s" ? amount * 1000 : amount;
}

const MULTIPLIERS: Record<string, number> = {
  ms: 1,
  s: 1000,
  m: 60_000,
  h: 3_600_000,
};

/**
 * Parse a duration string like "500ms", "2s", "3m", or "1h" into milliseconds.
 * Bare numbers are treated as milliseconds. Returns null for invalid input.
 */
export function parseMillis(value: string): number | null {
  const match = /^(\d+(?:\.\d+)?)(ms|s|m|h)?$/.exec(value.trim());
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  const unit = match[2] ?? "ms";
  const multiplier = MULTIPLIERS[unit];
  if (multiplier === undefined || !Number.isFinite(amount)) {
    return null;
  }

  return amount * multiplier;
}

